Here is the problem description:
<description>
Alice and Bob are playing a game with a string of characters, with Alice going first. The string consists n characters, each of which is one of the first k letters of the alphabet. On a player’s turn, they can either arbitrarily permute the characters in the words, or delete exactly one character in the word (if there is at least one character). In addition, their resulting word cannot have appeared before throughout the entire game. The player unable to make a valid move loses the game.Given n, k, p, find the number of words with exactly n characters consisting of the first k letters of the alphabet such that Alice will win if both Alice and Bob play optimally. Return this number modulo the prime number p.
</description>

Here is the input specification:
<input_spec>
The first line of input will contain three integers n, k, p (1 ≤ n ≤ 250 000, 1 ≤ k ≤ 26, 108 ≤ p ≤ 109 + 100, p will be prime).
</input_spec>

Here are additional notes:
<notes>
NoteThere are 14 strings that that Alice can win with. For example, some strings are "bbaa" and "baaa". Alice will lose on strings like "aaaa" or "bbbb".
</notes>

Here are sample inputs:
<sample_inputs>
<input>
4 2 100000007
</input>
</sample_inputs>

Here is the source code:
<source_code>
// In the name of God

#include<bits/stdc++.h>

#define F first
#define S second
#define PB push_back
#define sz(s) int((s).size())
#define bit(n,k) (((n)>>(k))&1)

using namespace std;

typedef long long ll;
typedef pair<int,int> pii;
typedef pair<ll,ll> pll;
typedef unsigned int ui;

const int Lg=18,Tw=(1<<Lg),Max=Tw+10;

int Ans[Max][Lg+3],tmp[Lg+3],tmp2[Lg+3],fac[Max],ifac[Max],N,n,mod=1e9+7;

int Pow(int a,int b){
    int ans=1;
    while(b){
	if(b&1) ans=1ll*ans*a %mod;
	a=1ll*a*a %mod;
	b>>=1;
    }
    return ans;
}
inline void Add(int *a,int *b){
    for(int i=0;i<=N;i++)
	a[i]=(a[i]+b[i])%mod;
}
inline void Sub(int *a,int *b){
    for(int i=0;i<=N;i++)
	a[i]=(a[i]-b[i])%mod;
}
inline void Mul(int *ans,int *a,int *b){
    memset(tmp,0,sizeof tmp);
    for(int i=0;i<=N;i++){
	for(int j=0;j<=i;j++){
	    tmp[i]=(1ll*tmp[i]+1ll*a[j]*b[i-j])%mod;
	}
    }
    memcpy(ans,tmp,sizeof tmp);
}
void trans1(int a[][Lg+3]){
    for(int i=0;i<N;i++)
	for(int msk=n;msk>=0;msk--)
	    if(bit(msk,i))
		Add(a[msk],a[msk ^ (1<<i)]);
}
void trans2(int a[][Lg+3]){
    for(int i=0;i<N;i++)
	for(int msk=n;msk>=0;msk--)
	    if(bit(msk,i))
		Sub(a[msk],a[msk ^ (1<<i)]);
}

vector<int>vec;

int main(){
    int K;cin>>n>>K>>mod;
    int ANS=Pow(K,n);
    if(n&1) return cout<<ANS<<endl,0;
    N=__builtin_popcount(n);
    int Nbef=n;
    for(int i=0;i<Lg;i++){
	if(bit(n,i))
	    vec.PB(i);
    }
    n=(1<<N)-1;
    fac[0]=1;
    for(int i=1;i<Max;i++)
	fac[i]=1ll*i*fac[i-1]%mod;
    ifac[Max-1]=Pow(fac[Max-1],mod-2);
    for(int i=Max-2;i>=0;i--)
	ifac[i]=1ll*(i+1)*ifac[i+1] %mod;
    for(int i=0;i<=n;i++){
	int Real=0;
	for(int j=0;j<N;j++)
	    Real+=bit(i,j)*(1<<vec[j]);
	Ans[i][__builtin_popcount(i)]=ifac[Real];
    }
    trans1(Ans);
    for(int i=0;i<=n;i++){
	int KK=K;
	memset(tmp2,0,sizeof tmp2); tmp2[0]=1;

	while(KK){
	    if(KK&1) Mul(tmp2,tmp2,Ans[i]);
	    Mul(Ans[i],Ans[i],Ans[i]);
	    KK>>=1;
	}
	memcpy(Ans[i],tmp2,sizeof tmp2);
    }
    trans2(Ans);
    ANS=(1ll*ANS-1ll*Ans[n][N]*fac[Nbef])%mod;
    if(ANS<0) ANS+=mod;	
    return cout<<ANS<<endl,0;
}

</source_code>
